#!/bin/bash
# Download all data needed for this environment.  Idempotent: every file is
# fetched only if it is missing.  Run on a node with internet access BEFORE
# submitting compute jobs (compute nodes have no internet).
#
# Estimated total download size: ~75 MB (zips); ~150 MB after extraction.
#
# 1. Procedural scenes (experiments parallel_lines*) need no download: train
#    scenes are generated by eval/train/, hidden test scenes by eval/test/.
# 2. Open-Structure benchmark (Li et al., RA-L 2024; the ICL-NUIM and TartanAir
#    factor graphs used by the paper's Tables 2-4), public on GitHub:
#      https://github.com/yanyan-li/Open-Structure/tree/main/dataset
#    For each sequence we fetch the initial factor graph (baseline.zip:
#    venom_sequence.txt, ground_truth.txt, ...) and the observation archive
#    (ground-truth landmarks).  Train sequences go to data/downloads/; the
#    held-out test sequences go to eval/test/downloads/ (hidden from solvers).
# 3. The upstream reference code under method/upstream/ is committed
#    (public: https://github.com/yanyan-li/RiemanLine).

set -e

WORKSPACE_DIR="$(cd "$(dirname "${BASH_SOURCE[0]}")/.." && pwd)"
cd "$WORKSPACE_DIR"

BASE_URL="https://raw.githubusercontent.com/yanyan-li/Open-Structure/7aaff32e72b82139a8fe56e26415fec16bbceacd/dataset"
TRAIN_SEQS="livingroom0 livingroom1 office0 office1 office japanesealley"
TEST_SEQS="livingroom2 livingroom3 office2 office3 hospital carwelding"

fetch_sequence() {
    local seq="$1" dest="$2"
    mkdir -p "$dest/$seq"
    for part in baseline observation; do
        local zip="$dest/$seq/$part.zip"
        if [ ! -s "$zip" ]; then
            echo "fetching $seq/$part.zip"
            curl -sfL --retry 3 -o "$zip.part" "$BASE_URL/$seq/$part.zip"
            mv "$zip.part" "$zip"
        fi
        local stamp="$dest/$seq/.$part.extracted"
        if [ ! -f "$stamp" ]; then
            # text files only (livingroom0's observation.zip also holds an image archive)
            python3 - "$zip" "$dest/$seq" <<'PY'
import sys, zipfile, pathlib
zf = zipfile.ZipFile(sys.argv[1])
out = pathlib.Path(sys.argv[2]).resolve()
for info in zf.infolist():
    if info.is_dir() or not info.filename.endswith(".txt"):
        continue
    target = (out / info.filename).resolve()
    if out not in target.parents:
        raise SystemExit(f"unsafe path in archive: {info.filename}")
    target.parent.mkdir(parents=True, exist_ok=True)
    target.write_bytes(zf.read(info))
PY
            touch "$stamp"
        fi
    done
}

for seq in $TRAIN_SEQS; do
    fetch_sequence "$seq" data/downloads/open_structure
done
for seq in $TEST_SEQS; do
    fetch_sequence "$seq" eval/test/downloads/open_structure
done
echo "Open-Structure sequences ready."
